<?php
use PHPUnit\Framework\TestCase;

/** Actual pure source in existing trusted PHP -n, never a candidate runtime. */
final class SourcePolicyMinimumPreflightIsolationTest extends TestCase {
	/** @dataProvider semantic_controls */
	public function test_extension_free_contract_and_assertion_killed_controls($mutation,$status) {
		$root=dirname(__DIR__);$before=array();foreach(array('launch-data','preflight-transcript') as $name){$file=$root.'/scripts/manual/source-policy-minimum-'.$name.'.php';$before[$file]=hash_file('sha256',$file);}
		$p=proc_open(array(PHP_BINARY,'-n','-d','disable_functions=json_encode,json_decode',$root.'/tests/support/source-policy-minimum-preflight-controls.php','--synthetic-preflight-control',$root,$mutation),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);$this->assertIsResource($p);fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$this->assertSame($status,proc_close($p),$mutation.':'.$err);$this->assertSame('',$err);$this->assertSame(0===$status?'contract-pass':'contract-killed',$out,$mutation);foreach($before as $file=>$hash)$this->assertSame($hash,hash_file('sha256',$file));
	}
	public static function semantic_controls(){return array_map(function($v){return array($v,'none'===$v?0:1);},array('none','path','dependency','environment','role','runtime','modules','module-path','frame','channel','clock','cleanup','stderr'));}
	public function test_transcript_alone_composes_without_catalog_or_launch_data() {
		$file=dirname(__DIR__).'/scripts/manual/source-policy-minimum-preflight-transcript.php';$hash=hash_file('sha256',$file);
		$code='require $argv[1];$c="Alynt_Drime_Backups_Dashboard_Minimum_Preflight_Transcript";$r=str_repeat("a",32);$h=str_repeat("b",64);$bind=array("base"=>array("pid"=>101,"start"=>"123"),"mysqli"=>array("pid"=>102,"start"=>"124"));$mods=array("base"=>array("sha256"=>$h,"count"=>4),"mysqli"=>array("sha256"=>$h,"count"=>5));$o=new $c($r,$h,$bind,$h,$h,$mods);$ok=true;$now=0;foreach(array("base","mysqli") as $s){$events=array(array("worker","start",array($bind[$s]["start"],"4b06073dd8230421ba701a677dd8b1aa23ed55706663d3fdf996702b557f83b2")),array("worker","profile",$c::profile_fields($s,$h,$h)),array("worker","held",array("await-observer")),array("controller","modules",array($h,(string)$mods[$s]["count"])),array("stdin","ack",array()),array("worker","released",array("acknowledged")),array("controller","exit",array("0","drained")),array("controller","cleanup",array("process-absent","unchanged","base"===$s?"retained-owned":"artifacts-absent")));foreach($events as $i=>$e){$line="ack"===$e[1]?$c::ack_frame($r,$h,$s,$bind[$s]["pid"]):$c::frame($r,$h,$s,$bind[$s]["pid"],$i+1,$e[1],$e[2]);$ok=$o->{$e[0]}($line,$now++)&&$ok;}}$ok=$ok&&$o->snapshot()["synthetic_complete"]&&!$o->snapshot()["execution"]&&!function_exists("adbmin_catalog")&&!class_exists("Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data",false)&&1===count(get_included_files())&&!function_exists("json_encode")&&!extension_loaded("mysqli");echo $ok?"standalone-pass":"standalone-fail";exit($ok?0:1);';
		$p=proc_open(array(PHP_BINARY,'-n','-d','disable_functions=json_encode,json_decode','-r',$code,$file),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);$this->assertIsResource($p);fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$this->assertSame(0,proc_close($p),$err);$this->assertSame('',$err);$this->assertSame('standalone-pass',$out);$this->assertSame($hash,hash_file('sha256',$file));
	}
	public function test_pure_call_surface_cannot_discover_read_launch_or_load() {
		$allowed=array('is_string','is_int','is_array','strlen','preg_match','count','array_keys','in_array','substr','strpos','strtolower','hash','implode','range','ksort','min','invalidargumentexception');
		$methods=array('application_hashes','dependencies','digest','inspect','runtime_template','runtime_data','module_data','module_rows','header','start_tick','profile_fields','fields','frame','ack_frame','reject','time','next','consume','worker','controller','stdin','stderr','eof','snapshot');
		foreach(array('launch-data','preflight-transcript') as $name){$source=file_get_contents(dirname(__DIR__).'/scripts/manual/source-policy-minimum-'.$name.'.php');$tokens=array_values(array_filter(token_get_all($source),function($t){return !is_array($t)||!in_array($t[0],array(T_WHITESPACE,T_COMMENT,T_DOC_COMMENT),true);}));
			foreach($tokens as $i=>$token){if(!is_array($token))continue;$next=$tokens[$i+1]??null;$prev=$tokens[$i-1]??null;$this->assertNotContains($token[0],array(T_EVAL,T_ECHO,T_PRINT,T_EXIT,T_INCLUDE,T_INCLUDE_ONCE,T_REQUIRE,T_GLOBAL),$name);if(T_VARIABLE===$token[0]){$this->assertNotContains($token[1],array('$_GET','$_POST','$_SERVER','$_ENV','$GLOBALS','$argv'));$this->assertNotSame('(',$next,'Dynamic callable forbidden');if(is_array($next)){$this->assertNotSame(T_DOUBLE_COLON,$next[0],'Dynamic class forbidden');if(T_OBJECT_OPERATOR===$next[0])$this->assertSame('$this',$token[1]);}}
				if(T_NEW===$token[0])$this->assertSame('InvalidArgumentException',$next[1]);if(T_STRING===$token[0]&&is_array($next)&&T_DOUBLE_COLON===$next[0])$this->assertSame('self',$token[1]);
				if(T_STRING===$token[0]&&'('===$next&&(!is_array($prev)||T_FUNCTION!==$prev[0])){$member=is_array($prev)&&in_array($prev[0],array(T_DOUBLE_COLON,T_OBJECT_OPERATOR),true);$this->assertTrue($member?in_array($token[1],$methods,true):(in_array(strtolower($token[1]),$allowed,true)||'adbmin_path'===$token[1]||'adbmin_catalog'===$token[1]),$token[1]);}
			}
			$this->assertSame('launch-data'===$name?1:0,substr_count($source,'require_once __DIR__'));if('launch-data'===$name)$this->assertStringContainsString("require_once __DIR__ . '/source-policy-minimum-artifacts.php';",$source);else{$this->assertStringNotContainsString('require',$source);$this->assertStringNotContainsString('Minimum_Launch_Data',$source);}$this->assertStringNotContainsString('source-policy-minimum-acquire',$source);$this->assertStringNotContainsString('source-policy-minimum-static',$source);
		}
		$this->assertStringNotContainsString('source-policy-minimum-',file_get_contents(dirname(__DIR__).'/alynt-drime-backups-dashboard.php'));
	}
}
